import {
  absoluteColumn2,
  absoluteArrayColumn2
} from "./repository-cache-qnc92qwc.js";
import {
  Timestamps2
} from "./repository-cache-qfa1cgps.js";

// src/project/sql.ts
import { isNotNull, isNull, ne, or } from "drizzle-orm";
import { sqliteTable, text, integer, primaryKey } from "drizzle-orm/sqlite-core";
var ProjectTable2 = sqliteTable("project", {
  id: text().$type().primaryKey(),
  worktree: absoluteColumn2().notNull(),
  vcs: text().$type(),
  name: text(),
  icon_url: text(),
  icon_url_override: text(),
  icon_color: text(),
  ...Timestamps2,
  time_initialized: integer(),
  time_active: integer().notNull().default(0).$defaultFn(() => Date.now()),
  time_archived: integer(),
  sandboxes: absoluteArrayColumn2().notNull(),
  commands: text({ mode: "json" }).$type()
});
var ProjectDirectoryTable2 = sqliteTable("project_directory", {
  project_id: text().$type().notNull().references(() => ProjectTable2.id, { onDelete: "cascade" }),
  directory: absoluteColumn2().notNull(),
  type: text().$type(),
  strategy: text(),
  time_created: integer().notNull().$default(() => Date.now())
}, (table) => [primaryKey({ columns: [table.project_id, table.directory] })]);
function upsertProject2(db, project) {
  const vcs = project.vcs?.type;
  return db.insert(ProjectTable2).values({ id: project.id, worktree: project.canonical, vcs, sandboxes: [] }).onConflictDoUpdate({
    target: ProjectTable2.id,
    set: { vcs: vcs ?? null },
    setWhere: vcs ? or(isNull(ProjectTable2.vcs), ne(ProjectTable2.vcs, vcs)) : isNotNull(ProjectTable2.vcs)
  }).run();
}

export { ProjectTable2, ProjectDirectoryTable2, upsertProject2 };
